(()=>{
 const isTyping=()=>/^(INPUT|TEXTAREA|SELECT)$/.test(document.activeElement?.tagName);
 const visible=el=>!!(el.offsetWidth||el.offsetHeight||el.getClientRects().length)&&!el.disabled;
 function move(list,delta){const items=[...list].filter(visible);if(!items.length)return;let i=items.indexOf(document.activeElement);i=i<0?(delta>0?-1:0):i;items[(i+delta+items.length)%items.length].focus()}
 function helpContent(){if(document.getElementById('memoryDump'))return '<p><kbd>Tab</kbd> элементы</p><p><kbd>← →</kbd> варианты взлома</p><p><kbd>↑ ↓</kbd> переход по строкам</p><p><kbd>Enter</kbd> выбрать</p><p><kbd>R</kbd> новый дамп</p><p><kbd>Esc</kbd> вернуться</p>';if(document.querySelector('.file-link'))return '<p><kbd>1–4</kbd> открыть файл</p><p><kbd>↑ ↓</kbd> выбрать файл</p><p><kbd>Enter</kbd> открыть</p><p><kbd>Esc</kbd> вернуться в Сеть 06</p>';return '<p><kbd>1–7</kbd> разделы сети</p><p><kbd>← →</kbd> листать микроридер</p><p><kbd>↑ ↓</kbd> навигация</p><p><kbd>Enter</kbd> открыть</p><p><kbd>/</kbd> поиск</p><p><kbd>Esc</kbd> закрыть окно</p>'}
 const toggle=document.createElement('button');toggle.className='keyboard-help-toggle';toggle.type='button';toggle.textContent='[?] КЛАВИАТУРА';toggle.setAttribute('aria-expanded','false');const panel=document.createElement('aside');panel.className='keyboard-help';panel.hidden=true;panel.innerHTML='<h2>УПРАВЛЕНИЕ</h2>'+helpContent();document.body.append(panel,toggle);function toggleHelp(){panel.hidden=!panel.hidden;toggle.setAttribute('aria-expanded',String(!panel.hidden))}toggle.addEventListener('click',toggleHelp);
 document.addEventListener('keydown',e=>{
  document.body.classList.add('keyboard-mode');
  if(e.key==='?'||e.key==='F1'){e.preventDefault();toggleHelp();return}
  if(document.getElementById('connectionOverlay')){window.TerminalAudio?.unlock();return}
  if(e.key==='Escape'){const dlg=[...document.querySelectorAll('dialog[open]')].at(-1);if(dlg){e.preventDefault();if(dlg.id==='accessDialog'&&document.getElementById('hackView'))location.href='fourth.html';else dlg.close();return}if(location.pathname.endsWith('fourth.html')||location.pathname.endsWith('secure.html')){location.href=location.pathname.endsWith('secure.html')?'fourth.html':'index.html';return}}
  if(document.getElementById('leisureDialog')?.open||isTyping()){return}
  const fileLinks=document.querySelectorAll('.file-link');if(fileLinks.length){if(/^[1-4]$/.test(e.key)){e.preventDefault();fileLinks[Number(e.key)-1]?.click();return}if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();move(fileLinks,e.key==='ArrowDown'?1:-1);return}}
  const access=document.getElementById('accessDialog');if(access?.open&&(e.key==='ArrowLeft'||e.key==='ArrowRight')){e.preventDefault();move(access.querySelectorAll('button'),e.key==='ArrowRight'?1:-1);return}
  const hack=document.getElementById('hackView');if(hack&&!hack.classList.contains('hidden')){const opts=hack.querySelectorAll('.word:not(.used),.bracket:not(.used)');if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();const delta=e.key==='ArrowLeft'?-1:e.key==='ArrowRight'?1:e.key==='ArrowUp'?-2:2;move(opts,delta);return}if(e.key.toLowerCase()==='r'){e.preventDefault();document.getElementById('restartHack')?.click();return}}
  const nav=document.querySelectorAll('.sidebar .nav-item');if(nav.length){if(/^[1-7]$/.test(e.key)){e.preventDefault();nav[Number(e.key)-1]?.click();return}if((e.key==='ArrowDown'||e.key==='ArrowUp')&&(document.activeElement===document.body||document.activeElement.closest?.('.sidebar'))){e.preventDefault();move(nav,e.key==='ArrowDown'?1:-1);return}if(e.key==='/'&&!e.ctrlKey&&!e.metaKey&&!e.altKey){e.preventDefault();document.getElementById('searchInput')?.focus();return}const rows=document.querySelectorAll('.doc-row');if(rows.length&&document.activeElement?.classList.contains('doc-row')&&(e.key==='ArrowDown'||e.key==='ArrowUp')){e.preventDefault();move(rows,e.key==='ArrowDown'?1:-1)}}
 });
 document.addEventListener('pointerdown',()=>document.body.classList.remove('keyboard-mode'),{passive:true});
})();
